\operatorname{proj}_{\mathbf{a}} \mathbf{a} &= \frac{\mathbf{a} \cdot \mathbf{a}}{\|\mathbf{a}\|^2} \mathbf{a} = \frac{\|\mathbf{a}\|^2}{\|\mathbf{a}\|^2} \mathbf{a} = \mathbf{a}, \\
\operatorname{proj}_{\mathbf{b}} \mathbf{a} &= \frac{\mathbf{a} \cdot \mathbf{b}}{\|\mathbf{b}\|^2} \mathbf{b}.
\end{align*}

